INSERT INTO lessons (level_id,lesson_key,sort_order,title,title_translation,description,primary_outcome_key,estimated_duration_sec,source_hash,status,metadata)
VALUES (@level_id,'EN-A1-L-0020',20,'Room two at seven','اتاق دو، ساعت هفت','مرور ترکیبی شماره اتاق و ساعت برنامه','A1-INTERACTION-CONFIRM-ROOM-TIME',420,'362710cb7dd645d4b5eebc745ce9051a5ed3f2d3f29eb2d2bd34d4a89c2b6582','validated','{"outcomeFa":"می توانی شماره اتاق و ساعت یک برنامه ساده را در یک موقعیت روشن بفهمی و کوتاه بازگو کنی.","scenarioFa":"برای یک برنامه دیگر به مرکز محله برگشته ای. این بار باید هم شماره اتاق و هم ساعت را روشن کنی. نقش تو نینا است.","prerequisiteOutcomeKeys":["A1-INTERACTION-CHOOSE-ROOM","A1-INTERACTION-ASK-TIME"],"curriculum":{"startingKnowledge":"early_a1_after_greetings","targetConstructions":[],"supportLanguage":[],"assessmentBoundary":"Guided speech is supported read-aloud practice. Choice tasks assess recognition or selection. Final hidden-answer retrieval records bounded first-attempt evidence; exact text matching does not certify open-ended ability or pronunciation.","transferPlan":{"mode":"same_lesson","intent":"End with a meaning-cued hidden-answer retrieval or recombination and continue delayed review in later stories."},"story":{"arcKey":"EN-A1-COMMUNITY","sceneKey":"EN-A1-SCENE-0020","learnerRoleKey":"nina","participants":["nina","iris"],"introducedCharacterKeys":[],"relationshipState":"already_known","continuesLessonKey":"EN-A1-L-0014","dependsOnLessonKeys":["EN-A1-L-0014"],"settingFa":"مرکز محله، تایید اتاق و ساعت یک برنامه جدید","storyBeatFa":"نینا و آیریس این بار دو بخش از اطلاعات برنامه را کنار هم می گذارند: شماره اتاق و ساعت."},"reviewLinks":[{"lessonKey":"EN-A1-L-0014","activityKeys":["A02","A03"],"learningDemand":"retrieval","note":"Retrieve room-number language after six Lesson positions in the returning community arc."},{"lessonKey":"EN-A1-L-0016","activityKeys":["A02","A04","A05"],"learningDemand":"transfer","note":"Recombine familiar time language with a room number instead of using time alone."}],"pedagogyVersion":2},"audioRequired":true,"humanEnglishAuditRequired":true,"dialogueRuntime":"guided_exchange"}')
ON DUPLICATE KEY UPDATE level_id=VALUES(level_id),sort_order=VALUES(sort_order),title=VALUES(title),title_translation=VALUES(title_translation),description=VALUES(description),primary_outcome_key=VALUES(primary_outcome_key),estimated_duration_sec=VALUES(estimated_duration_sec),source_hash=VALUES(source_hash),status=VALUES(status),metadata=VALUES(metadata);
SET @lesson_id=(SELECT id FROM lessons WHERE level_id=@level_id AND lesson_key='EN-A1-L-0020' LIMIT 1);
DELETE FROM lesson_lexical_items WHERE lesson_id=@lesson_id;

-- Keep existing activities IDs; remove only keys absent from this Lesson source.
DELETE FROM activities WHERE lesson_id=@lesson_id AND activity_key NOT IN ('A01','A02','A03','A04','A05');
SET @child_order_offset=(SELECT GREATEST(COALESCE(MAX(sort_order),0),5) FROM activities WHERE lesson_id=@lesson_id);
UPDATE activities SET sort_order=sort_order+@child_order_offset WHERE lesson_id=@lesson_id ORDER BY sort_order DESC;

-- Keep existing lesson_turns IDs; remove only keys absent from this Lesson source.
DELETE FROM lesson_turns WHERE lesson_id=@lesson_id AND turn_key NOT IN ('T01','T02','T03','T04','T05','T06');
SET @child_order_offset=(SELECT GREATEST(COALESCE(MAX(sort_order),0),6) FROM lesson_turns WHERE lesson_id=@lesson_id);
UPDATE lesson_turns SET sort_order=sort_order+@child_order_offset WHERE lesson_id=@lesson_id ORDER BY sort_order DESC;

