INSERT INTO activities (lesson_id,activity_key,sort_order,activity_type,instruction,prompt,config,metadata)
VALUES (@lesson_id,'A03',3,'comprehension','گوش کن و با توجه به چیزی که شنیدی پاسخ بده.','آیریس برای برنامه جدید کدام اتاق و ساعت را می گوید؟','{"sourceTurnKeys":["T05"],"options":["اتاق یک، ساعت شش","اتاق دو، ساعت هفت","اتاق دو، ساعت شش"],"answerIndex":1,"transcriptAfterAttempt":true,"feedback":{"optionsFa":["در صدا Room two و At seven گفته می شود؛ این گزینه هر دو بخش را عوض می کند.","Room two. At seven. یعنی اتاق دو، ساعت هفت.","شماره اتاق درست است اما زمان در صدا seven است، نه six."],"correctFa":"Room two. At seven. یعنی اتاق دو، ساعت هفت."}}','{"learningDemand":"transfer","purpose":"Combine two familiar details from one short listening clip.","evidenceKind":"recognition_or_selection"}')
