INSERT INTO activities (lesson_id,activity_key,sort_order,activity_type,instruction,prompt,config,metadata)
VALUES (@lesson_id,'A04',4,'response_choice','با توجه به موقعیت، گزینه مناسب را انتخاب کن.','آیریس می پرسد What time? و تو می دانی برنامه ساعت شش است. کدام پاسخ مناسب است؟','{"optionsEn":["Room one.","At six.","On Tuesday."],"answerIndex":1,"feedback":{"optionsFa":["این پاسخ شماره اتاق است، نه زمان.","این پاسخ ساعت شش را می گوید.","این پاسخ روز سه شنبه را می گوید، نه ساعت."],"correctFa":"این پاسخ ساعت شش را می گوید."}}','{"learningDemand":"changed_context","purpose":"changed_context","evidenceKind":"recognition_or_selection"}')
